local function cite(el)
  if #el.citations ~= 1 then return nil end
  local id = el.citations[1].id
  local p = prelim[id]
  if p then
    local suffix = (lang == 'en') and '' or ('.' .. lang)
    local target = FORMAT:match('html') and (p[2] .. suffix .. '.html') or ('#' .. id)
    return pandoc.Link({ pandoc.Str(p[1]) }, target)
  end
  local title = course[id]
  if title then
    return pandoc.Emph(pandoc.Inlines((course_label[lang] or course_label.en) .. title))
  end
end

return {
  { Meta = function(meta) if meta.lang then lang = pandoc.utils.stringify(meta.lang):sub(1, 2) end end },
  { Cite = cite }
}
